(4759491, 686599, 30049, '<td valign="top">Cute kid.  I''m not sure if the focal plane is that short, or you did some selective sharpening, maybe even selective softening, but the boys mouth and nose seem unnaturally soft in comparison to the rest of the photo.</td>', 'Cute kid.  I''m not sure if the focal plane is that short, or you did some selective sharpening, maybe even selective softening, but the boys mouth and nose seem unnaturally soft in comparison to the rest of the photo.', '2008-06-09 12:36:15.000000', NULL, 1),
(4759496, 687024, 30049, '<td valign="top">Nice portrait.  Having a hard time making this fit with the challenge theme.  Yes, this young lad is a "cowboy" by wearing a hat, but it feels quite staged, like something you''d put on (a prop) in a studio for a portrait setting.  Quality is certainly there, although I''m leaning more toward the images that have more of an authentic feel to them.  All JMO of course.  Good luck in the challenge.</td>', 'Nice portrait.  Having a hard time making this fit with the challenge theme.  Yes, this young lad is a "cowboy" by wearing a hat, but it feels quite staged, like something you''d put on (a prop) in a studio for a portrait setting.  Quality is certainly there, although I''m leaning more toward the images that have more of an authentic feel to them.  All JMO of course.  Good luck in the challenge.', '2008-06-09 12:38:40.000000', NULL, 1),
(4759497, 685841, 30049, '<td valign="top">Hmmm.  Not sure whether to laugh or cry.  I understand the sentiment, but the "tear" seems a little overstated.  On a technical note, the white in the beard has a strong bluish cast.</td>', 'Hmmm.  Not sure whether to laugh or cry.  I understand the sentiment, but the "tear" seems a little overstated.  On a technical note, the white in the beard has a strong bluish cast.', '2008-06-09 12:40:24.000000', NULL, 1),
(4759498, 686835, 30049, '<td valign="top">Yep.  Ok.  Cute.</td>', 'Yep.  Ok.  Cute.', '2008-06-09 12:40:50.000000', NULL, 1),
(4759499, 686476, 30049, '<td valign="top">Looks like an advertisement for a studio portrait shop.</td>', 'Looks like an advertisement for a studio portrait shop.', '2008-06-09 12:41:27.000000', NULL, 1),
(4759502, 686856, 30049, '<td valign="top">Are ''Grape Wranglers'' cowboys?!  Looks like a statue you''d see at a winery.  As a photo, the image is composed just fine.  The colorcast is a little on the orangy side IMO.  Good luck in the challenge.</td>', 'Are ''Grape Wranglers'' cowboys?!  Looks like a statue you''d see at a winery.  As a photo, the image is composed just fine.  The colorcast is a little on the orangy side IMO.  Good luck in the challenge.', '2008-06-09 12:42:44.000000', NULL, 1),
(4759503, 686151, 30049, '<td valign="top">I don''t think this is the type of "Cowboy" in mind for the challenge.  Nice cloud formations however.  :-)</td>', 'I don''t think this is the type of "Cowboy" in mind for the challenge.  Nice cloud formations however.  :-)', '2008-06-09 12:43:36.000000', NULL, 1),
(4759505, 687021, 30049, '<td valign="top">This image feels really awkward and difficult to figure out.</td>', 'This image feels really awkward and difficult to figure out.', '2008-06-09 12:44:34.000000', NULL, 1),
(4759507, 686014, 30049, '<td valign="top">Pretty much a snapshot IMO. Cool boots thou...have never seen them with that type of tread/sole before.</td>', 'Pretty much a snapshot IMO. Cool boots thou...have never seen them with that type of tread/sole before.', '2008-06-09 12:45:24.000000', NULL, 1),
(4759508, 686919, 66515, '<td valign="top">Not sure about the processing but there''s no denying that this little one is cute. I''d like to see more space in front of him to give him something to run into.</td>', 'Not sure about the processing but there''s no denying that this little one is cute. I''d like to see more space in front of him to give him something to run into.', '2008-06-09 12:45:36.000000', NULL, 1),
(4759509, 686769, 30049, '<td valign="top">I like the environmental portrait feel to this.  I''m a little uncomfortable with the extreme processing - seems substantially overworked IMO.</td>', 'I like the environmental portrait feel to this.  I''m a little uncomfortable with the extreme processing - seems substantially overworked IMO.', '2008-06-09 12:46:35.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4759510, 686574, 30049, '<td valign="top">Just a tad blurry.  Seems a little over the top on HDR for my taste.  Good luck in the challenge.</td>', 'Just a tad blurry.  Seems a little over the top on HDR for my taste.  Good luck in the challenge.', '2008-06-09 12:46:39.000000', NULL, 1),
(4759511, 687002, 30049, '<td valign="top">What the ???!  Looks like some sort of body part, and not a pleasant one at that.</td>', 'What the ???!  Looks like some sort of body part, and not a pleasant one at that.', '2008-06-09 12:47:16.000000', NULL, 1),
(4759514, 686779, 30049, '<td valign="top">A neglected tourist attraction?</td>', 'A neglected tourist attraction?', '2008-06-09 12:47:58.000000', NULL, 1),
(4759515, 686996, 66515, '<td valign="top">Nice tribute. I really like the pastoral feeling you''ve captured. The horse appears to be bowing his head in silence too. I can also see he wants to sniff at the model too! :) <br/> <br/>Great capture and one that I am sure Sean would have liked.</td>', 'Nice tribute. I really like the pastoral feeling you''ve captured. The horse appears to be bowing his head in silence too. I can also see he wants to sniff at the model too! :)  Great capture and one that I am sure Sean would have liked.', '2008-06-09 12:48:01.000000', NULL, 1),
(4759516, 686267, 30049, '<td valign="top">Nice equipment type photo.  Could be an ad for a tack shop.  Seems overly busy to me with all of this "gear".</td>', 'Nice equipment type photo.  Could be an ad for a tack shop.  Seems overly busy to me with all of this "gear".', '2008-06-09 12:48:49.000000', NULL, 1),
(4759519, 686657, 30049, '<td valign="top">Kind of a neat approach to the challenge.  A unique POV for the composition.  A bit heavy-handed on the noise reduction is giving it a comical/cartoonish feel IMO.</td>', 'Kind of a neat approach to the challenge.  A unique POV for the composition.  A bit heavy-handed on the noise reduction is giving it a comical/cartoonish feel IMO.', '2008-06-09 12:50:08.000000', NULL, 1),
(4759521, 686955, 30049, '<td valign="top">A nice B/W conversion in covering the tonal range.  Something about the composition doesn''t feel right.   I think it''s the busy background and cutting off the horse''s head.  Good catchlights in the man''s eyes.</td>', 'A nice B/W conversion in covering the tonal range.  Something about the composition doesn''t feel right.   I think it''s the busy background and cutting off the horse''s head.  Good catchlights in the man''s eyes.', '2008-06-09 12:51:36.000000', NULL, 1),
(4759522, 687000, 30049, '<td valign="top">Looks like a kid from the 60''s with the color and post-processing treatment given.  I do wish his face was a little sharper.</td>', 'Looks like a kid from the 60''s with the color and post-processing treatment given.  I do wish his face was a little sharper.', '2008-06-09 12:52:24.000000', NULL, 1),
(4759524, 686909, 30049, '<td valign="top">Nice backlighting overall.  I''m guessing you intentionally wanted the bright light to be subliminally representative of the afterlife?  It''s a risky move (the extreme lighting) for scoring well, but it is a fresh take from a photography standpoint.  Good luck in the challenge.</td>', 'Nice backlighting overall.  I''m guessing you intentionally wanted the bright light to be subliminally representative of the afterlife?  It''s a risky move (the extreme lighting) for scoring well, but it is a fresh take from a photography standpoint.  Good luck in the challenge.', '2008-06-09 12:54:15.000000', NULL, 1),
(4759525, 686842, 83032, '<td valign="top">DNMC</td>', 'DNMC', '2008-06-09 12:54:18.000000', NULL, 1),
(4759527, 686889, 83032, '<td valign="top">DNMC</td>', 'DNMC', '2008-06-09 12:55:13.000000', NULL, 1),
(4759528, 686937, 30049, '<td valign="top">Big sky, small horse - cool minimalistic approach.  Sepia works well.  Good luck in the challenge.</td>', 'Big sky, small horse - cool minimalistic approach.  Sepia works well.  Good luck in the challenge.', '2008-06-09 12:55:32.000000', NULL, 1),
(4759529, 686835, 83032, '<td valign="top">DNMC</td>', 'DNMC', '2008-06-09 12:56:24.000000', NULL, 1),
(4759532, 687031, 83032, '<td valign="top">DNMC</td>', 'DNMC', '2008-06-09 12:57:17.000000', NULL, 1),
(4759534, 686868, 30049, '<td valign="top">Fun idea, and a good title.  The PP is perhaps a tad extreme with the harsh lighting feel to it.  JMO of course.  Good luck in the challenge.</td>', 'Fun idea, and a good title.  The PP is perhaps a tad extreme with the harsh lighting feel to it.  JMO of course.  Good luck in the challenge.', '2008-06-09 12:58:37.000000', NULL, 1),
(4759535, 687033, 30049, '<td valign="top">Looks like somebody went shooting together for this.  :-)  I like this post-processing of the sky better in this.  Having a cutesy foal/colt in the comp will certainly boost the score.  Title works well also.  Good luck.</td>', 'Looks like somebody went shooting together for this.  :-)  I like this post-processing of the sky better in this.  Having a cutesy foal/colt in the comp will certainly boost the score.  Title works well also.  Good luck.', '2008-06-09 12:58:39.000000', NULL, 1),
(4759536, 686916, 30049, '<td valign="top">I like the expression captured.  The B/W works well also.  Good luck.</td>', 'I like the expression captured.  The B/W works well also.  Good luck.', '2008-06-09 12:59:21.000000', NULL, 1),
(4759537, 687023, 30049, '<td valign="top">Hmmm.  Certainly an artistic/poetic approach.  The photo and title together make a good combination.</td>', 'Hmmm.  Certainly an artistic/poetic approach.  The photo and title together make a good combination.', '2008-06-09 13:00:15.000000', NULL, 1),
(4759542, 686211, 30049, '<td valign="top">From this angle the bull looks twice as large as the cow.  Lighting is a little harsh, but hey, what are you going to do?  Get the capture when you can.  :-)  Good luck.</td>', 'From this angle the bull looks twice as large as the cow.  Lighting is a little harsh, but hey, what are you going to do?  Get the capture when you can.  :-)  Good luck.', '2008-06-09 13:01:46.000000', NULL, 1),
(4759544, 686680, 30049, '<td valign="top">Ok photo.  Thin connection IMO to the challenge.  Something about the glasses seems out of place,</td>', 'Ok photo.  Thin connection IMO to the challenge.  Something about the glasses seems out of place,', '2008-06-09 13:02:51.000000', NULL, 1),
(4759546, 687026, 30049, '<td valign="top">This works well in B/W.  Focal point seems off a tad.  The bull appears OOF and the trees/shrubs in the background are sharper.</td>', 'This works well in B/W.  Focal point seems off a tad.  The bull appears OOF and the trees/shrubs in the background are sharper.', '2008-06-09 13:03:54.000000', NULL, 1),
(4759550, 687032, 30049, '<td valign="top">Cute kid.  This would have been a great shot for the recent portrait challenge.  It fit''s "ok" for this challenge...personally I''m leaning more toward the authentic cowboy feel that some have presented.  Best of luck to you in the challenge.</td>', 'Cute kid.  This would have been a great shot for the recent portrait challenge.  It fit''s "ok" for this challenge...personally I''m leaning more toward the authentic cowboy feel that some have presented.  Best of luck to you in the challenge.', '2008-06-09 13:05:23.000000', NULL, 1),
(4759551, 686964, 30049, '<td valign="top">Cute kid.  This would have been a great shot for the recent portrait challenge.  It fit''s "ok" for this challenge...personally I''m leaning more toward the authentic cowboy feel that some have presented.  Best of luck to you in the challenge.</td>', 'Cute kid.  This would have been a great shot for the recent portrait challenge.  It fit''s "ok" for this challenge...personally I''m leaning more toward the authentic cowboy feel that some have presented.  Best of luck to you in the challenge.', '2008-06-09 13:05:34.000000', NULL, 1),
(4759552, 685990, 30049, '<td valign="top">A little bit of motion blur it looks like, and somewhat overprocessed.  Wondering why you didn''t use an action shot after he left the gate - that would have been sweet!  Good luck.</td>', 'A little bit of motion blur it looks like, and somewhat overprocessed.  Wondering why you didn''t use an action shot after he left the gate - that would have been sweet!  Good luck.', '2008-06-09 13:05:38.000000', NULL, 1),
(4759553, 686325, 66515, '<td valign="top">Looks more like The Man with No Name (ie The character Clint Eastwood portrays in The Good The Bad and The Ugly as well as a Fistful of Dollars and a Few Dollars more).<br/> <br/>Aside from that, the mood is great in this shot and is definitely a good depiction of the rugged western gunslinger. A fun interpretation of the challenge.</td>', 'Looks more like The Man with No Name (ie The character Clint Eastwood portrays in The Good The Bad and The Ugly as well as a Fistful of Dollars and a Few Dollars more). Aside from that, the mood is great in this shot and is definitely a good depiction of the rugged western gunslinger. A fun interpretation of the challenge.', '2008-06-09 13:05:57.000000', NULL, 1),
(4759555, 686914, 66515, '<td valign="top">A little dark. I''d like to see more light on his body as well as his face. I like the emotion captured in what I can see of his face. Unfortunately, our sad cowboy has a cactus growing out of his hat.</td>', 'A little dark. I''d like to see more light on his body as well as his face. I like the emotion captured in what I can see of his face. Unfortunately, our sad cowboy has a cactus growing out of his hat.', '2008-06-09 13:08:00.000000', NULL, 1),
