(4759691, 686476, 73942, '<td valign="top">he''s awful cute, I think this would of worked better with just the Li''l Buckaroo and his hat on the florr, his pose is perfect</td>', 'he''s awful cute, I think this would of worked better with just the Li''l Buckaroo and his hat on the florr, his pose is perfect', '2008-06-09 14:37:03.000000', NULL, 1),
(4759726, 686955, 76598, '<td valign="top">It seems odd to have the horse''s head partially cut off.</td>', 'It seems odd to have the horse''s head partially cut off.', '2008-06-09 14:56:48.000000', NULL, 1),
(4759728, 686812, 76598, '<td valign="top">over saturated</td>', 'over saturated', '2008-06-09 14:57:19.000000', NULL, 1),
(4759740, 686324, 67237, '<td valign="top">one of my picks for top 5</td>', 'one of my picks for top 5', '2008-06-09 15:06:41.000000', NULL, 1),
