(4760347, 686709, 59029, '<td valign="top">very odd shot for this challenge, the harmonica does not look real.  The notes are clearly not.</td>', 'very odd shot for this challenge, the harmonica does not look real.  The notes are clearly not.', '2008-06-09 21:16:25.000000', NULL, 1),
(4760348, 686916, 59029, '<td valign="top">Good shot, much more natural and convincing than many of the overly posed babies and kutesy kids. 8</td>', 'Good shot, much more natural and convincing than many of the overly posed babies and kutesy kids. 8', '2008-06-09 21:17:24.000000', NULL, 1),
(4760350, 687023, 59029, '<td valign="top">Tremendous shot.  Wish I had done it, glad you did. 10</td>', 'Tremendous shot.  Wish I had done it, glad you did. 10', '2008-06-09 21:17:53.000000', NULL, 1),
(4760352, 686697, 59029, '<td valign="top">great comp and like the anonymity, the timelessness of this shot. 9</td>', 'great comp and like the anonymity, the timelessness of this shot. 9', '2008-06-09 21:18:53.000000', NULL, 1),
(4760353, 686551, 59029, '<td valign="top">again, so glad someone actually found an old cowboy and caught him in a relaxed moment. 9</td>', 'again, so glad someone actually found an old cowboy and caught him in a relaxed moment. 9', '2008-06-09 21:19:41.000000', NULL, 1),
(4760358, 686328, 59029, '<td valign="top">Ok picture, but too centred and flat.</td>', 'Ok picture, but too centred and flat.', '2008-06-09 21:21:01.000000', NULL, 1),
(4760362, 684886, 59029, '<td valign="top">good textures but the boots look brand-new and virtually unworn.  I''d rather see them scuffed, dirty and creased with age.</td>', 'good textures but the boots look brand-new and virtually unworn.  I''d rather see them scuffed, dirty and creased with age.', '2008-06-09 21:22:25.000000', NULL, 1),
(4760366, 686267, 59029, '<td valign="top">Too posed.  Pity, because with all the props you just need a horse to toss the saddle and Navajo pad on, hang the hat and lariat from the horn, and have the boots facing backwards in the stirrups to signify that the rider has passed on.</td>', 'Too posed.  Pity, because with all the props you just need a horse to toss the saddle and Navajo pad on, hang the hat and lariat from the horn, and have the boots facing backwards in the stirrups to signify that the rider has passed on.', '2008-06-09 21:24:50.000000', NULL, 1),
