(4760411, 686710, 51538, '<td valign="top">I like the dynamic moment.  A fitting tribute to a person so full of life. 9.</td>', 'I like the dynamic moment.  A fitting tribute to a person so full of life. 9.', '2008-06-09 21:45:26.000000', NULL, 1),
(4760413, 686617, 51538, '<td valign="top">Friendship is a worthy aspect of our relationship with this DPC hero.  Nicely composed photo. 9.</td>', 'Friendship is a worthy aspect of our relationship with this DPC hero.  Nicely composed photo. 9.', '2008-06-09 21:46:04.000000', NULL, 1),
(4760436, 686774, 70265, '<td valign="top">Very nice portrait. I like the sharpness and detail in the face, works well in black &amp; white.</td>', 'Very nice portrait. I like the sharpness and detail in the face, works well in black & white.', '2008-06-09 22:14:12.000000', NULL, 1),
(4760437, 686885, 70265, '<td valign="top">One of my ribbon picks. I think silos are very difficult to pull off, but you''ve done it here. Background colors are simply gorgeous, and I find myself wondering if they are the real thing ...</td>', 'One of my ribbon picks. I think silos are very difficult to pull off, but you''ve done it here. Background colors are simply gorgeous, and I find myself wondering if they are the real thing ...', '2008-06-09 22:14:26.000000', NULL, 1),
(4760439, 685066, 70265, '<td valign="top">Just beautiful! I know this is a tough exposure, but you''ve done it here. Composition spot on, sepia a perfect choice. Well done!</td>', 'Just beautiful! I know this is a tough exposure, but you''ve done it here. Composition spot on, sepia a perfect choice. Well done!', '2008-06-09 22:14:36.000000', NULL, 1),
(4760442, 686398, 70265, '<td valign="top">Beautiful composition. Love the low key and sepia. Hope you do well with this.</td>', 'Beautiful composition. Love the low key and sepia. Hope you do well with this.', '2008-06-09 22:14:43.000000', NULL, 1),
(4760443, 686325, 70265, '<td valign="top">A perfect Clint! Love the detail in the face, the sepia, his expression. The cigar puts it over the top. Clearly, one of my top three ...</td>', 'A perfect Clint! Love the detail in the face, the sepia, his expression. The cigar puts it over the top. Clearly, one of my top three ...', '2008-06-09 22:14:52.000000', NULL, 1),
(4760445, 686710, 70265, '<td valign="top">Great stopped action. Beautiful colors. Nice DOF. I like that the fence is on a tilt also. Good luck with this.</td>', 'Great stopped action. Beautiful colors. Nice DOF. I like that the fence is on a tilt also. Good luck with this.', '2008-06-09 22:15:03.000000', NULL, 1),
(4760446, 685996, 70265, '<td valign="top">Interesting and effective perspective. Love the black &amp; white here. Title is perfect. Great job!</td>', 'Interesting and effective perspective. Love the black & white here. Title is perfect. Great job!', '2008-06-09 22:15:21.000000', NULL, 1),
(4760447, 687024, 70265, '<td valign="top">Great catchlight in the eyes, perfect expression. i gave it an 8.</td>', 'Great catchlight in the eyes, perfect expression. i gave it an 8.', '2008-06-09 22:15:27.000000', NULL, 1),
(4760448, 686832, 70265, '<td valign="top">Muted tones work well here. Great composition also.</td>', 'Muted tones work well here. Great composition also.', '2008-06-09 22:15:32.000000', NULL, 1),
