(4761652, 686774, 30049, '<td valign="top">A nice portrait, done well in B/W.  Good touch in selectively sharpening the eyes.  Good luck in the challenge.</td>', 'A nice portrait, done well in B/W.  Good touch in selectively sharpening the eyes.  Good luck in the challenge.', '2008-06-10 15:37:20.000000', NULL, 1),
(4761654, 686268, 30049, '<td valign="top">A fun, cute, gimmicky shot.  May be a little on the plain side.</td>', 'A fun, cute, gimmicky shot.  May be a little on the plain side.', '2008-06-10 15:38:28.000000', NULL, 1),
(4761655, 686726, 30049, '<td valign="top">Good work with the selective desat.  I''d have tried to find a spot more rustic than a manicured lawn however.  :-)</td>', 'Good work with the selective desat.  I''d have tried to find a spot more rustic than a manicured lawn however.  :-)', '2008-06-10 15:39:38.000000', NULL, 1),
(4761660, 686624, 30049, '<td valign="top">Nice and neat and tidy!  :-)  The bullets laid out so neatly really make this feel extremely contrived and void of emotive value.  JMO of course.  :-)  Good luck in the challenge.</td>', 'Nice and neat and tidy!  :-)  The bullets laid out so neatly really make this feel extremely contrived and void of emotive value.  JMO of course.  :-)  Good luck in the challenge.', '2008-06-10 15:42:31.000000', NULL, 1),
(4761662, 686328, 30049, '<td valign="top">Who shrunk the boots?!  Some nice threads there.  For a B/W it''s coming up short in tonal range and coming across a bit flat.</td>', 'Who shrunk the boots?!  Some nice threads there.  For a B/W it''s coming up short in tonal range and coming across a bit flat.', '2008-06-10 15:43:44.000000', NULL, 1),
(4761669, 686454, 30049, '<td valign="top">Nice low-key shot.  Good work on the technicals.  I''m kind of on the fence post if it''s doing anything for me as far as an emotional connection.  Seems a little static and impersonal IMO.</td>', 'Nice low-key shot.  Good work on the technicals.  I''m kind of on the fence post if it''s doing anything for me as far as an emotional connection.  Seems a little static and impersonal IMO.', '2008-06-10 15:46:42.000000', NULL, 1),
(4761671, 686752, 30049, '<td valign="top">That''s an intense gaze for sure.  I didn''t know cowboys wore button collar shirts?  :-)</td>', 'That''s an intense gaze for sure.  I didn''t know cowboys wore button collar shirts?  :-)', '2008-06-10 15:48:05.000000', NULL, 1),
(4761847, 687033, 811, '<td valign="top">The composition in this is wonderful and I like how the horses are isolated from everything except eachother.</td>', 'The composition in this is wonderful and I like how the horses are isolated from everything except eachother.', '2008-06-10 17:30:25.000000', NULL, 1),
(4761848, 686937, 811, '<td valign="top">Great use of negative space.</td>', 'Great use of negative space.', '2008-06-10 17:30:41.000000', NULL, 1),
