(4761851, 686398, 811, '<td valign="top">My favorite in the challenge.  The lighting on this is, imo, perfect.  Enough is lit that it is obvious it is a "cowboy," but enough is "hidden," that it could be any man.  Great composition.</td>', 'My favorite in the challenge.  The lighting on this is, imo, perfect.  Enough is lit that it is obvious it is a "cowboy," but enough is "hidden," that it could be any man.  Great composition.', '2008-06-10 17:31:49.000000', NULL, 1),
(4761852, 685066, 811, '<td valign="top">An instance where a centered composition works really well.  Nicely done.</td>', 'An instance where a centered composition works really well.  Nicely done.', '2008-06-10 17:32:13.000000', NULL, 1),
(4761901, 686885, 1024, '<td valign="top">This is a lovely and touching tribute.  You have done well.</td>', 'This is a lovely and touching tribute.  You have done well.', '2008-06-10 18:03:52.000000', NULL, 1),
(4761904, 687033, 1024, '<td valign="top">I love the dreamy feel here, almost like a pastoral meadow.  Lovely tribute. 10</td>', 'I love the dreamy feel here, almost like a pastoral meadow.  Lovely tribute. 10', '2008-06-10 18:04:38.000000', NULL, 1),
