(4764738, 686710, 90663, '<td valign="top">Nice action shot, really like the horse''s expression here, and the highlights off the horse''s coat are spot on.</td>', 'Nice action shot, really like the horse''s expression here, and the highlights off the horse''s coat are spot on.', '2008-06-11 18:59:15.000000', NULL, 1),
(4764740, 685774, 90663, '<td valign="top">Very effective use of dreamy soft focus here, I''m not a fan of borders and perhaps would have liked the horse a little less centered in the frame, but overall very nice, an 8 from me</td>', 'Very effective use of dreamy soft focus here, I''m not a fan of borders and perhaps would have liked the horse a little less centered in the frame, but overall very nice, an 8 from me', '2008-06-11 18:59:19.000000', NULL, 1),
