(4764946, 686921, 51747, '<td valign="top">Great texture. The lighting is very nice</td>', 'Great texture. The lighting is very nice', '2008-06-11 21:24:06.000000', NULL, 1),
(4764948, 686857, 51747, '<td valign="top">I didn''t see the tongue at first, when I did it made me laugh. Nice job.</td>', 'I didn''t see the tongue at first, when I did it made me laugh. Nice job.', '2008-06-11 21:25:13.000000', NULL, 1),
