(4765056, 687002, 70514, '<td valign="top">I''m normally a fan of grain, but this doesn''t do it for me.  I can''t really figure out what the subject is. Sorry.</td>', 'I''m normally a fan of grain, but this doesn''t do it for me.  I can''t really figure out what the subject is. Sorry.', '2008-06-11 23:15:37.000000', NULL, 1),
(4765057, 686678, 70514, '<td valign="top">A beautifully composed image with a lovely conversion.  Nicely done.</td>', 'A beautifully composed image with a lovely conversion.  Nicely done.', '2008-06-11 23:16:23.000000', NULL, 1),
