(4765382, 686996, 82707, '<td valign="top">Nice shot. Lovely tribute. Bump.</td>', 'Nice shot. Lovely tribute. Bump.', '2008-06-12 01:28:42.000000', NULL, 1),
(4765398, 686328, 71244, '<td valign="top">I really like this set up, but why are the boots so small?</td>', 'I really like this set up, but why are the boots so small?', '2008-06-12 01:43:24.000000', NULL, 1),
(4765475, 687021, 66515, '<td valign="top">Really curious to see how this was done. Interesting shot and a nice take on the challenge.</td>', 'Really curious to see how this was done. Interesting shot and a nice take on the challenge.', '2008-06-12 02:37:31.000000', NULL, 1),
(4765476, 687000, 66515, '<td valign="top">Nice shot with an interesting pose. Focus seems to be touch off however</td>', 'Nice shot with an interesting pose. Focus seems to be touch off however', '2008-06-12 02:38:17.000000', NULL, 1),
(4765478, 685990, 66515, '<td valign="top">Interesting shot but the processing has created some rather unpleasant posterization.</td>', 'Interesting shot but the processing has created some rather unpleasant posterization.', '2008-06-12 02:38:57.000000', NULL, 1),
(4765479, 687022, 66515, '<td valign="top">A little more light on the left would help us see more detail especially in the buckle. Wish I could see what rodeo this was for... :)</td>', 'A little more light on the left would help us see more detail especially in the buckle. Wish I could see what rodeo this was for... :)', '2008-06-12 02:40:12.000000', NULL, 1),
(4765480, 686476, 66515, '<td valign="top">Interesting idea and a cute model. A few too many toys though have made the scene quite busy. Putting the hat on him would have been reeeeally cute btw.</td>', 'Interesting idea and a cute model. A few too many toys though have made the scene quite busy. Putting the hat on him would have been reeeeally cute btw.', '2008-06-12 02:42:31.000000', NULL, 1),
(4765481, 686921, 66515, '<td valign="top">Interesting take on the challenge. I like the b&amp;w conversion as it has nicely brought out some interesting textures</td>', 'Interesting take on the challenge. I like the b&w conversion as it has nicely brought out some interesting textures', '2008-06-12 02:44:13.000000', NULL, 1),
(4765482, 685066, 66515, '<td valign="top">Effective silhouette. Nice subtle details in the background. The positioning of the man and the horse works well to create a strong connection between them</td>', 'Effective silhouette. Nice subtle details in the background. The positioning of the man and the horse works well to create a strong connection between them', '2008-06-12 02:45:09.000000', NULL, 1),
(4765483, 686398, 66515, '<td valign="top">effective use of lighting to really create a sense of ruggedness in the model. Some might not agree with going without a title. I believe that its a better way to go sometimes. A great shot that I think Sean would have enjoyed.</td>', 'effective use of lighting to really create a sense of ruggedness in the model. Some might not agree with going without a title. I believe that its a better way to go sometimes. A great shot that I think Sean would have enjoyed.', '2008-06-12 02:46:38.000000', NULL, 1),
(4765484, 686812, 66515, '<td valign="top">Interesting use of HDR. I like the subtleties of the background showing the western lifestyle without taking too much attention from the boots.</td>', 'Interesting use of HDR. I like the subtleties of the background showing the western lifestyle without taking too much attention from the boots.', '2008-06-12 02:47:31.000000', NULL, 1),
(4765485, 686832, 66515, '<td valign="top">I like the dramatic sky that you''ve captured here. The posts and barb wire work well to bring your eye to the had. Great textures in the old wood of the posts.  Well done</td>', 'I like the dramatic sky that you''ve captured here. The posts and barb wire work well to bring your eye to the had. Great textures in the old wood of the posts.  Well done', '2008-06-12 02:48:37.000000', NULL, 1),
(4765487, 686551, 66515, '<td valign="top">Some may have been tempted to go black and white however I like this as it is. Great capture showing nice emotion in the model. The fact that he is smoking adds just a bit of extra interest to the shot.</td>', 'Some may have been tempted to go black and white however I like this as it is. Great capture showing nice emotion in the model. The fact that he is smoking adds just a bit of extra interest to the shot.', '2008-06-12 02:49:59.000000', NULL, 1),
(4765488, 685473, 66515, '<td valign="top">Love the capture of the eyes in this shot. A real hard stare that comes from experience. The black and white conversion works well to show character in his face without making him look like a saddle bag with eye.</td>', 'Love the capture of the eyes in this shot. A real hard stare that comes from experience. The black and white conversion works well to show character in his face without making him look like a saddle bag with eye.', '2008-06-12 02:51:03.000000', NULL, 1),
(4765489, 685774, 66515, '<td valign="top">Great pastoral image. I love the soft dreamy look to the shot. The colors are nicely saturated without going overboard. A little bright across the horse''s back but I don''t think it takes away in this case. Normally I don''t care for anything but simple borders but this one works well with the image.</td>', 'Great pastoral image. I love the soft dreamy look to the shot. The colors are nicely saturated without going overboard. A little bright across the horse''s back but I don''t think it takes away in this case. Normally I don''t care for anything but simple borders but this one works well with the image.', '2008-06-12 02:52:33.000000', NULL, 1),
(4765492, 686777, 66515, '<td valign="top">Lots of boots in this challenge! I like how you have placed them with a wooden fence in the background. The coiled rope is a nice touch. (sadly not a lariat but oh well!) Good choice on the b&amp;w conversion but I am curious to see the color version for comparison sake.</td>', 'Lots of boots in this challenge! I like how you have placed them with a wooden fence in the background. The coiled rope is a nice touch. (sadly not a lariat but oh well!) Good choice on the b&w conversion but I am curious to see the color version for comparison sake.', '2008-06-12 02:54:35.000000', NULL, 1),
(4765493, 687030, 66515, '<td valign="top">A lot of great ideas in this shot. Everything in this shot is in tribute to Sean. Well executed.</td>', 'A lot of great ideas in this shot. Everything in this shot is in tribute to Sean. Well executed.', '2008-06-12 02:55:24.000000', NULL, 1),
(4765494, 686907, 66515, '<td valign="top">Strange to see so many "hats on fence post" shots. <br/> <br/>Nice "layering" with a bit of vegetation in the foreground, the hat and the fence in the midground and more vegetation in the background. <br/> <br/>Place of the hat and the posts in the frame could be a little stronger as it is quite central in the frame.</td>', 'Strange to see so many "hats on fence post" shots.  Nice "layering" with a bit of vegetation in the foreground, the hat and the fence in the midground and more vegetation in the background.  Place of the hat and the posts in the frame could be a little stronger as it is quite central in the frame.', '2008-06-12 02:58:06.000000', NULL, 1),
(4765495, 686802, 66515, '<td valign="top">Interesting take on the challenge. I''d personally like to see more of the left hand boot. I''d also like to see a far less prominent border as it really draws the eye away from the elements in the frame.</td>', 'Interesting take on the challenge. I''d personally like to see more of the left hand boot. I''d also like to see a far less prominent border as it really draws the eye away from the elements in the frame.', '2008-06-12 02:59:42.000000', NULL, 1),
(4765540, 685066, 72689, '<td valign="top">I love it: composition, square format, tones. The stance of the cowboy and the horse - I can feel nearness between them. The stand of the horse - it seems so obedient. <br/>Don''t know why - the picture gives me some sad feeling... But a very good photo.</td>', 'I love it: composition, square format, tones. The stance of the cowboy and the horse - I can feel nearness between them. The stand of the horse - it seems so obedient. Don''t know why - the picture gives me some sad feeling... But a very good photo.', '2008-06-12 04:53:14.000000', NULL, 1),
(4766012, 686617, 88054, '<td valign="top">Very nicely done. Beautiful tribute.</td>', 'Very nicely done. Beautiful tribute.', '2008-06-12 12:49:01.000000', NULL, 1),
(4766015, 686885, 88054, '<td valign="top">Very well done.</td>', 'Very well done.', '2008-06-12 12:50:34.000000', NULL, 1),
(4766022, 686774, 88054, '<td valign="top">Very nicely done</td>', 'Very nicely done', '2008-06-12 12:54:12.000000', NULL, 1),
(4766024, 685774, 88054, '<td valign="top">What a gorgeous picture.</td>', 'What a gorgeous picture.', '2008-06-12 12:55:07.000000', NULL, 1),
(4766030, 687012, 88054, '<td valign="top">This is very well done. The lighting is excellent. Thoughtful title and message.</td>', 'This is very well done. The lighting is excellent. Thoughtful title and message.', '2008-06-12 12:58:39.000000', NULL, 1),
(4766032, 687030, 88054, '<td valign="top">Awesome.</td>', 'Awesome.', '2008-06-12 12:59:30.000000', NULL, 1),
(4766403, 686802, 77192, '<td valign="top">More sharpened than my taste, but nice and bright</td>', 'More sharpened than my taste, but nice and bright', '2008-06-12 17:22:09.000000', NULL, 1),
(4766405, 686812, 77192, '<td valign="top">not keen on the background but the tonemapping works well here.</td>', 'not keen on the background but the tonemapping works well here.', '2008-06-12 17:22:46.000000', NULL, 1),
(4766410, 685473, 77192, '<td valign="top">You can see all those year sou ton the range on his face. you''ve captured the details incredibly well.</td>', 'You can see all those year sou ton the range on his face. you''ve captured the details incredibly well.', '2008-06-12 17:24:23.000000', NULL, 1),
(4766415, 687032, 77192, '<td valign="top">love his expression.<br/> <br/>"Git off your hoss and drink your milk!"</td>', 'love his expression. "Git off your hoss and drink your milk!"', '2008-06-12 17:27:05.000000', NULL, 1),
(4766416, 686211, 77192, '<td valign="top">LOL!<br/> <br/>She doesn''t look fabulously keen ;-)</td>', 'LOL! She doesn''t look fabulously keen ;-)', '2008-06-12 17:27:54.000000', NULL, 1),
(4766420, 686955, 77192, '<td valign="top">He looks quite troubled almost. (The man that is, not the horse)</td>', 'He looks quite troubled almost. (The man that is, not the horse)', '2008-06-12 17:28:48.000000', NULL, 1),
(4766421, 687024, 94473, '<td valign="top">I love this shot, the clarity is superb, very natural portrait. Well done.</td>', 'I love this shot, the clarity is superb, very natural portrait. Well done.', '2008-06-12 17:28:54.000000', NULL, 1),
(4766423, 687021, 77192, '<td valign="top">Love to know how this was done.<br/> <br/>A terrific tribute to <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=66348" rel="nofollow" target="_blank">jawnyrico</a></td>', 'Love to know how this was done. A terrific tribute to  jawnyrico', '2008-06-12 17:29:58.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4766428, 686842, 77192, '<td valign="top">Pushing the challenge a bit, but I''ll let you off as it''s a great capture. Plus they do look a bit like they''re riding horses.</td>', 'Pushing the challenge a bit, but I''ll let you off as it''s a great capture. Plus they do look a bit like they''re riding horses.', '2008-06-12 17:31:58.000000', NULL, 1),
(4766543, 686574, 92601, '<td valign="top">I''m not really digging the effects here</td>', 'I''m not really digging the effects here', '2008-06-12 18:40:33.000000', NULL, 1),
(4766684, 686268, 76430, '<td valign="top">Very creative shot.</td>', 'Very creative shot.', '2008-06-12 20:40:53.000000', NULL, 1),
(4766691, 686868, 76430, '<td valign="top">Two SP''s in a row <img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=16197" rel="nofollow" target="_blank">littlegett</a>.  This time I''m sure it''s you.  Not really a cowboy hat (and too small for you) or attire.  It''s a nice shot, well processed and would be much more fitting with the right hat and shirt.  What''s that white stuff behind your head?</td>', 'Two SP''s in a row  littlegett.  This time I''m sure it''s you.  Not really a cowboy hat (and too small for you) or attire.  It''s a nice shot, well processed and would be much more fitting with the right hat and shirt.  What''s that white stuff behind your head?', '2008-06-12 20:45:42.000000', NULL, 1),
(4766693, 687031, 76430, '<td valign="top">It''s a stretch for "The Cowboy".  whiterook?  Nice sharp boat and spray.</td>', 'It''s a stretch for "The Cowboy".  whiterook?  Nice sharp boat and spray.', '2008-06-12 20:49:46.000000', NULL, 1),
